def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    change = new - old
    return {
        "value": change,
        "trace": {
            "old_balance": old,
            "new_balance": new,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
